/* Lightweight Canvas Chart Renderer compatible with Chart.js API */
(function() {
  const PALETTE = ['#2563eb', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#ec4899'];

  window.Chart = function(ctx, config) {
    this.ctx = ctx;
    this.config = config || {};
    this.type = this.config.type || 'bar';
    this.data = this.config.data || { labels: [], datasets: [] };
    this.options = this.config.options || {};

    let canvas = null;
    if (typeof ctx === 'string') {
      canvas = document.getElementById(ctx);
    } else if (ctx && ctx.canvas) {
      canvas = ctx.canvas;
    } else {
      canvas = ctx;
    }
    this.canvas = canvas;

    this.render = function() {
      if (!this.canvas || !this.canvas.getContext) return;
      const c = this.canvas.getContext('2d');
      const w = this.canvas.width = this.canvas.clientWidth || 480;
      const h = this.canvas.height = this.canvas.clientHeight || 260;

      c.clearRect(0, 0, w, h);
      c.fillStyle = '#ffffff';
      c.fillRect(0, 0, w, h);

      const labels = this.data.labels || [];
      const dataset = (this.data.datasets && this.data.datasets[0]) || { data: [] };
      const values = (dataset.data || []).map(v => Number(v || 0));
      const maxVal = Math.max(...values, 1);

      const padLeft = 48;
      const padRight = 24;
      const padTop = 28;
      const padBottom = 42;
      const plotW = Math.max(w - padLeft - padRight, 50);
      const plotH = Math.max(h - padTop - padBottom, 50);

      // Draw axes
      c.strokeStyle = '#e2e8f0';
      c.lineWidth = 1;
      c.beginPath();
      c.moveTo(padLeft, padTop);
      c.lineTo(padLeft, padTop + plotH);
      c.lineTo(padLeft + plotW, padTop + plotH);
      c.stroke();

      if (values.length === 0) {
        c.fillStyle = '#64748b';
        c.font = '13px sans-serif';
        c.textAlign = 'center';
        c.fillText('No data to display', w / 2, h / 2);
        return;
      }

      if (this.type === 'pie' || this.type === 'doughnut') {
        const total = values.reduce((a, b) => a + b, 0) || 1;
        let angle = -Math.PI / 2;
        const cx = w / 2 - 40;
        const cy = h / 2;
        const r = Math.min(plotW, plotH) / 2.3;

        values.forEach((val, idx) => {
          const slice = (val / total) * Math.PI * 2;
          const colors = Array.isArray(dataset.backgroundColor) ? dataset.backgroundColor : PALETTE;
          c.fillStyle = colors[idx % colors.length];
          c.beginPath();
          c.moveTo(cx, cy);
          c.arc(cx, cy, r, angle, angle + slice);
          c.closePath();
          c.fill();
          angle += slice;
        });

        if (this.type === 'doughnut') {
          c.fillStyle = '#ffffff';
          c.beginPath();
          c.arc(cx, cy, r * 0.55, 0, Math.PI * 2);
          c.fill();
        }

        // Legend
        labels.forEach((lbl, idx) => {
          const colors = Array.isArray(dataset.backgroundColor) ? dataset.backgroundColor : PALETTE;
          const ly = padTop + idx * 20;
          c.fillStyle = colors[idx % colors.length];
          c.fillRect(w - 130, ly, 12, 12);
          c.fillStyle = '#334155';
          c.font = '11px sans-serif';
          c.textAlign = 'left';
          c.fillText(`${String(lbl).slice(0, 12)} (${values[idx]})`, w - 112, ly + 10);
        });
        return;
      }

      const step = plotW / Math.max(values.length, 1);

      if (this.type === 'line') {
        c.strokeStyle = (typeof dataset.borderColor === 'string' && dataset.borderColor) || PALETTE[0];
        c.lineWidth = 2.5;
        c.beginPath();
        values.forEach((val, idx) => {
          const x = padLeft + idx * step + step / 2;
          const y = padTop + plotH - (val / maxVal) * plotH;
          if (idx === 0) c.moveTo(x, y);
          else c.lineTo(x, y);
        });
        c.stroke();
      } else {
        // Bar chart
        const barW = Math.min(step * 0.6, 48);
        values.forEach((val, idx) => {
          const colors = Array.isArray(dataset.backgroundColor) ? dataset.backgroundColor : PALETTE;
          c.fillStyle = typeof dataset.backgroundColor === 'string' ? dataset.backgroundColor : colors[idx % colors.length];
          const bh = (val / maxVal) * plotH;
          const x = padLeft + idx * step + (step - barW) / 2;
          const y = padTop + plotH - bh;
          c.fillRect(x, y, barW, bh);
        });
      }

      // Labels
      c.fillStyle = '#475569';
      c.font = '11px sans-serif';
      c.textAlign = 'center';
      labels.forEach((lbl, idx) => {
        const x = padLeft + idx * step + step / 2;
        c.fillText(String(lbl).slice(0, 10), x, padTop + plotH + 18);
      });
    };

    this.update = function() {
      this.render();
    };

    this.destroy = function() {
      if (this.canvas && this.canvas.getContext) {
        const c = this.canvas.getContext('2d');
        c.clearRect(0, 0, this.canvas.width, this.canvas.height);
      }
    };

    this.render();
  };

  window.Chart.defaults = {};
})();
